 private void applyDebugCatSocialProbe(){WorldState s=state;if(s==null||s.world==null||s.catState==null)return;WorldArea home=s.world.area("home_shelter");if(home==null)return;s.haruX=300f;s.catState.x=480f;s.catX=480f;s.catState.areaId=home.id;s.catState.awake=true;s.catState.attachedToEntity="";s.catState.carryKnownByGirl=false;s.catState.energy=90;s.catState.sleepiness=10;s.catState.lastPlayerActiveAt=0;if(s.catSocial==null)s.catSocial=new CatSocialState();s.catSocial.familiarity=.86;s.catSocial.comfort=.82;s.catSocial.wariness=.06;s.catSocial.curiosity=.62;s.catSocial.mode="WATCH";s.catSocial.reason="";s.catSocial.activeTravelId="";s.catSocial.frozenTargetX=Float.NaN;s.catSocial.lastPlayerOverrideAt=0;s.catTravel=new TravelState();if(s.catPhysics!=null){s.catPhysics.falling=false;s.catPhysics.grounded=true;s.catPhysics.velocityX=0;s.catPhysics.velocityY=0;}if(s.girlTravel!=null)s.girlTravel.active=false;StateInvariantChecker.normalizeSpatialState(s,Math.max(System.currentTimeMillis(),s.lastSimulatedAt));gameView.postInvalidate();}
