 @Override public void onGod(){if(!worldReadyForInteraction())return;if(godScene!=null||gameRoot==null)return;if(gameView!=null)gameView.setDivineVisualPresence(true);godScene=new GodContactScene(this,godInboxSummary(),new GodContactScene.Host(){public void onClose(){closeGodScene();}public void onSend(String q){handleGodMessage(q);}});gameRoot.addView(godScene.view(),new FrameLayout.LayoutParams(-1,-1));godScene.setSessionState(GodSessionManager.getState());GodSessionManager.warmup(getApplicationContext());}
