 private void handleGodMessage(String raw){final GodContactScene target=godScene;if(target==null)return;if(looksLikeContentRollback(raw)){RuntimeContentUpdater.Result rr=RuntimeContentUpdater.rollback(getApplicationContext());if(gameView!=null)gameView.postInvalidate();target.showSystem(rr.ok?"Những thay đổi gần nhất đã lùi lại. Thế giới đã ổn định.":"Không có thay đổi nào có thể lùi lại lúc này.");return;}if(isLocalGodCapability(raw)){String out=GodContactController.handle(state,raw);rememberGod(raw,out);target.showSystem(out);return;}if(!VnfOnlineConfig.godConfigured()){target.showError("Không có lời đáp lúc này. Thế giới vẫn tiếp tục.");return;}GodOnlineClient.ask(getApplicationContext(),state,raw,(result,error)->runOnUiThread(()->{if(error!=null){if(godScene==target)target.showError("Không có lời đáp lúc này.");return;}if(result==null){if(godScene==target)target.showError("Chỉ còn một khoảng lặng.");return;}rememberGod(raw,result.reply);if(result.worldEventProposal!=null){long eventNow=Math.max(state.lastSimulatedAt,state.lastOpenedAt);GodWorldEventExecutor.Result er=GodWorldEventExecutor.apply(state,result.worldEventProposal,eventNow);if(er.ok){repository.save(state);if(gameView!=null)gameView.postInvalidate();}}if(godScene!=target)return;if(result.godRecipePayload!=null&&!result.godRecipePayload.isEmpty()){RuntimeContentUpdater.Result rr=SignedGodWorldRecipe.apply(getApplicationContext(),result.godRecipePayload,result.godRecipeSignature);if(gameView!=null)gameView.postInvalidate();target.showReply(result.reply);return;}if(result.autoApplyContentPatch&&!result.contentPatchManifestUrl.isEmpty()){target.showProgress(result.reply+"\n\nÁnh sáng quanh thế giới đang đổi khác…");RuntimeContentUpdater.applySignedManifestAsync(getApplicationContext(),result.contentPatchManifestUrl,pr->runOnUiThread(()->{if(gameView!=null)gameView.postInvalidate();if(godScene==target)target.showReply(pr.ok?"Mọi thứ đã lắng lại.":"Sự thay đổi đã dừng lại." );}));return;}target.showReply(result.reply);}));}
 private void rememberGod(String q,String a){if(state.godMemory==null)state.godMemory=new GodMemory();long n=Math.max(System.currentTimeMillis(),Math.max(state.lastOpenedAt,state.lastSimulatedAt));state.godMemory.remember(q,a,n);repository.save(state);}
 private boolean looksLikeContentRollback(String r){String q=r.toUpperCase(java.util.Locale.ROOT);return q.contains("ROLLBACK CONTENT")||q.contains("HOÀN TÁC ĐỒ HỌA")||q.contains("HOAN TAC DO HOA")||q.contains("KHÔI PHỤC WORLD CONTENT")||q.contains("KHOI PHUC WORLD CONTENT");}
 private boolean isLocalGodCapability(String r){String q=r.toUpperCase(java.util.Locale.ROOT);if(!DivineNamingEngine.extractProposal(r).isEmpty())return true;if(GodTeachingGateway.looksLikeTeaching(r))return true;return q.contains("TRẠNG THÁI")||q.contains("TRANG THAI")||q.contains("BẢO VỆ")||q.contains("BAO VE")||q.contains("ĐÁNH GIÁ")||q.contains("DANH GIA")||q.contains("CHẨN ĐOÁN")||q.contains("CHAN DOAN")||q.contains("TÊN")||q.contains("TEN");}
 @Override public void onConsole(){if(!worldReadyForInteraction())return;final EditText i=new EditText(this);i.setHint("TRẠNG THÁI / CHẨN ĐOÁN / ...");i.setSingleLine(true);new AlertDialog.Builder(this).setTitle("SYSTEM · Thần").setMessage("Chỉ những thay đổi an toàn của thế giới mới có thể được thực hiện tại đây.\n\nTest hình ảnh: DEV GOD VEIL / DEV GOD VEIL SEVERE").setView(i).setPositiveButton("Chạy",(d,w)->{String raw=i.getText().toString();if(runGodVeilTest(raw)||runHaruVisionTest(raw))return;String out=SystemConsole.execute(state,raw);repository.save(state);new AlertDialog.Builder(this).setTitle("SYSTEM").setMessage(out).setPositiveButton("Đóng",null).show();}).setNegativeButton("Đóng",null).show();}
 private boolean runGodVeilTest(String raw){String q=raw==null?"":raw.trim().toUpperCase(java.util.Locale.ROOT);boolean severe=q.equals("DEV GOD VEIL SEVERE")||q.equals("TEST BAI XICH")||q.equals("TEST BÀI XÍCH");boolean normal=q.equals("DEV GOD VEIL")||q.equals("TEST MAN THAN")||q.equals("TEST MÀN THẦN");if(!severe&&!normal)return false;if(gameView!=null)gameView.showGodVeilTest(severe);Toast.makeText(this,severe?"Đang thử màn chắn cấp cao.":"Đang thử màn ổn định thế giới.",Toast.LENGTH_SHORT).show();return true;}
 private boolean runHaruVisionTest(String raw){String q=raw==null?"":raw.trim().toUpperCase(java.util.Locale.ROOT);if(!q.equals("DEV HARU VISION")&&!q.equals("HARU VISION TEST"))return false;if(gameView!=null)gameView.showHaruVisionTest();Toast.makeText(this,"Đang hiển thị nhận thức hiện tại của Haru.",Toast.LENGTH_SHORT).show();return true;}
 private String godInboxSummary(){StringBuilder b=new StringBuilder("TIN TỪ THẦN\n\n");int start=Math.max(0,state.godInbox.size()-5);for(int i=start;i<state.godInbox.size();i++){GodMessage m=state.godInbox.get(i);b.append(m.read?"· ":"• ").append(m.text).append('\n');m.read=true;}if(state.godInbox.isEmpty())b.append("(chưa có lời nhắn)");repository.save(state);return b.toString();}
 private void maybeCheckAppUpdate(boolean force){long now=System.currentTimeMillis();if(!VnfOnlineConfig.appUpdaterConfigured()||updateCheckInFlight||updateDownloadInFlight||updateDialogVisible)return;if(!force&&now-lastUpdateCheckAt<UPDATE_RESUME_GUARD_MS)return;lastUpdateCheckAt=now;pendingUpdate=null;updateCheckInFlight=true;AppUpdateManager.checkAsync(getApplicationContext(),(u,e)->runOnUiThread(()->{updateCheckInFlight=false;if(e!=null){Log.w(TAG,"Update check failed",e);pendingUpdate=null;return;}if(u==null){pendingUpdate=null;return;}int installed=installedVersionCode();if(u.versionCode<=installed){pendingUpdate=null;return;}pendingUpdate=u;Log.i(TAG,"UPDATE_AVAILABLE versionCode="+u.versionCode+" autoDownload=true");downloadPendingUpdate();}));}
 private int installedVersionCode(){try{android.content.pm.PackageInfo p=getPackageManager().getPackageInfo(getPackageName(),0);return android.os.Build.VERSION.SDK_INT>=28?(int)p.getLongVersionCode():p.versionCode;}catch(Throwable ignored){return BuildConfig.VERSION_CODE;}}
 private void downloadPendingUpdate(){final AppUpdateManager.Update u=pendingUpdate;pendingUpdate=null;if(u==null||u.versionCode<=installedVersionCode()||updateDownloadInFlight)return;updateDownloadInFlight=true;Toast.makeText(this,"VNF đang tự tải và kiểm tra bản cập nhật…",Toast.LENGTH_SHORT).show();new Thread(()->{try{File apk=AppUpdateManager.downloadAndVerify(getApplicationContext(),u);runOnUiThread(()->{updateDownloadInFlight=false;Log.i(TAG,"UPDATE_READY versionCode="+u.versionCode+" verified=true");requestInstallOrLaunch(apk);});}catch(Throwable e){runOnUiThread(()->{updateDownloadInFlight=false;showUpdateError(e);});}},"VNF-App-Update-Download").start();}
 private void requestInstallOrLaunch(File apk){if(android.os.Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){pendingUpdateApk=apk;new AlertDialog.Builder(this).setTitle("CHO PHÉP CẬP NHẬT VNF").setMessage("Android cần bạn cho phép VNF cài bản cập nhật từ nguồn này. Sau khi bật quyền, quay lại VNF; màn hình xác nhận cài đặt sẽ tự mở.\n\nVNF không thể bỏ qua bước xác nhận của Android.").setPositiveButton("Mở cài đặt",(d,w)->{updateExternalFlow=true;try{startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(Throwable e){updateExternalFlow=false;showUpdateError(e);}}).setNegativeButton("Hủy",(d,w)->pendingUpdateApk=null).show();return;}launchUpdateInstaller(apk);}
 private void launchUpdateInstaller(File apk){updateExternalFlow=true;try{AppUpdateManager.launchInstaller(this,apk);}catch(Throwable e){updateExternalFlow=false;showUpdateError(e);}}
 private void showUpdateError(Throwable e){pendingUpdate=null;Log.e(TAG,"Update stopped",e);new AlertDialog.Builder(this).setTitle("CẬP NHẬT BỊ DỪNG").setMessage("Bản cập nhật chưa thể hoàn tất. VNF hiện tại, thế giới và ký ức vẫn được giữ nguyên.\n\nBạn có thể thử lại khi mở VNF lần sau.").setPositiveButton("Đóng",null).show();}
 private void showStartupFailure(Throwable e){Log.e(TAG,"World startup failed",e);TextView t=new TextView(this);t.setText("VNF đã mở ở chế độ an toàn.\n\nThế giới chưa được chạy để tránh làm hỏng ký ức hiện tại.\nDữ liệu không bị tự động xóa.\n\nHãy đóng rồi mở lại VNF. Nếu tình trạng vẫn lặp lại, giữ nguyên dữ liệu và kiểm tra bản cập nhật tiếp theo.");t.setTextColor(Color.rgb(241,229,201));t.setBackgroundColor(Color.rgb(18,31,33));t.setTextSize(18);int pad=(int)(24*getResources().getDisplayMetrics().density);t.setPadding(pad,pad,pad,pad);ScrollView s=new ScrollView(this);s.setBackgroundColor(Color.rgb(18,31,33));s.addView(t);setContentView(s);}private void maybeHaruRequestCoreRuntimePermissions(){if(permissionRequestIntroVisible||isFinishing()||isDestroyed())return;boolean mic=checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED;boolean notifications=android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED;if(!mic&&!notifications)return;permissionRequestIntroVisible=true;String message;if(mic&&notifications)message="Mình muốn nghe được khi bạn nói với mình. Và nếu có chuyện đáng để gọi bạn khi bạn không ở đây, mình cũng muốn tự báo cho bạn.\n\nBạn cho mình hai quyền đó nhé?";else if(mic)message="Mình muốn nghe được khi bạn nói với mình, thay vì bắt bạn phải gõ mọi lúc.\n\nBạn cho mình quyền dùng micro nhé?";else message="Nếu có chuyện thật sự đáng để gọi bạn khi bạn không ở đây, mình muốn có thể tự báo cho bạn.\n\nBạn cho mình quyền gửi thông báo nhé?";new AlertDialog.Builder(this).setTitle("Haru chủ động hỏi").setMessage(message).setPositiveButton("Cho phép",(d,w)->{permissionRequestIntroVisible=false;requestCoreRuntimePermissions();}).setNegativeButton("Chưa",(d,w)->permissionRequestIntroVisible=false).setOnCancelListener(d->permissionRequestIntroVisible=false).show();}private void requestCoreRuntimePermissions(){java.util.ArrayList<String> missing=new java.util.ArrayList<>();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)missing.add(Manifest.permission.RECORD_AUDIO);if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)missing.add(Manifest.permission.POST_NOTIFICATIONS);if(!missing.isEmpty())requestPermissions(missing.toArray(new String[0]),403);}private void hideSystemUi(){if(android.os.Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);WindowInsetsController c=getWindow().getInsetsController();if(c!=null)c.hide(WindowInsets.Type.systemBars());}else getWindow().getDecorView().setSystemUiVisibility(5894);}
